  enunciado:"Assinale a alternativa correta em relação à Atenção Primária à Saúde.",
  alternativas:[{id:"A",texto:"Deve ser a única porta de entrada tanto para problemas agudos quanto crônicos."},{id:"B",texto:"A atenção primária se restringe a países ou locais com maior vulnerabilidade social."},{id:"C",texto:"Proporciona atenção à saúde da população sem distinção de gênero, doença ou sistema orgânico."},{id:"D",texto:"O termo prevenção serve como sinônimo de “cuidado a pessoas que não têm sintomas”."}],
  gabarito:"C",
