  areaId:"area-mps", especialidadeId:"esp-epidemio", assuntoId:"ass-prevencao",
  enunciado:"Assinale a alternativa correta em relação ao rastreamento de doenças.",
  alternativas:[{id:"A",texto:"O viés de sobrediagnóstico constitui-se em um dos principais problemas de saúde pública atribuídos aos programas de rastreamento que não é eliminado por meio dos ensaios clínicos randomizados."},{id:"B",texto:"É uma intervenção que não oferece risco potencial à saúde das pessoas sem o respectivo benefício."},{id:"C",texto:"Avaliação de procedimentos de rastreamento é técnica e eticamente fácil, pois envolve vieses e fenômenos simples."},{id:"D",texto:"É a aplicação de testes em pessoas sintomáticas com objetivo de selecionar indivíduos para intervenções cujo benefício potencial seja maior do que o dano potencial."}],
  gabarito:"A",
  explicacaoGeral:"A alternativa A é a do gabarito oficial. O sobrediagnóstico (diagnóstico de doenças que nunca causariam sintomas) é problema reconhecido do rastreamento e **não é eliminado pelos ensaios clínicos randomizados**, que também o sofrem. Todo rastreamento tem riscos potenciais (B errada), sua avaliação é complexa (C) e se faz em pessoas **assintomáticas** (D errada).",
  explicacoesAlternativas:{},
  referencias:"Gordis L. Epidemiologia, 5ª ed. Rio de Janeiro: Revinter, 2017.",
  dificuldadeManual:"intermediario", status:"ativa",
  estatisticas:{respostas:0, acertos:0, distribuicaoAlternativas:{}},
